using static StrataLint.Scribe.DefinitionDsl;
namespace StrataLint.Scribe.Blueprint.D5.S3.Combinatorics.Circle.FourNegative.SecondPeakIndependentTailInterior;
internal sealed class ArithmeticDocument : IScribeDocumentDefinition
{
    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "Native masks and exact heights", H("All independent dyadic parameters"),
        Blocks(Paragraph(Text("The rational coordinates of D0 and W0 equal the sums of the distinct physical bits in their supports. All complementary weights follow from exhaustive finite inventories, including the W high-mask complement above bit s+1. Thus every natural mask is identified with the corresponding rational model entry. When r=a-c-d is zero, the three c cases and the actual half-unit rounding error give the boundary charts. When r is positive, t=2^r=2(2^(r-1)) and K is 4 or 2 at r=1, 3 at r=2, and 1 at r>=3. These values satisfy 1<=K<=4 and give the uniform even-rounding charts. The resulting seams and peak slacks are nonnegative for all c>=2,d>=c+2,a>=c+d,b>=a+1, including zero individual masks and the minimal dyadic q=1."))), []));
}
